-- 建表脚本：每次启动都会执行（spring.sql.init.mode=always）。
-- 只在表不存在时建表，已有表和数据原样保留（不再 DROP），重启后数据不丢。
-- 如需彻底重置开发数据，停掉后端后删除 backend/prodDb.mv.db 再启动即可。


-- Create tables

CREATE TABLE IF NOT EXISTS roles (
    -- H2 2.x 推荐使用 GENERATED BY DEFAULT AS IDENTITY 替代 AUTO_INCREMENT
                       role_id INT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) PRIMARY KEY,
                       role_name VARCHAR(255) NOT NULL,
                       description TEXT
);

CREATE TABLE IF NOT EXISTS departments (
                             department_id INT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) PRIMARY KEY,
                             department_name VARCHAR(255) NOT NULL,
                             parent_department_id INT
    -- 外键约束在 users 表创建后再添加
);

CREATE TABLE IF NOT EXISTS users (
                       user_id VARCHAR(255) PRIMARY KEY,
                       username VARCHAR(255) NOT NULL UNIQUE,
                       password_hash VARCHAR(255) NOT NULL,
                       email VARCHAR(255) UNIQUE,
                       full_name VARCHAR(255),
                       role_id INT,
                       department_id INT,
                       mbti_type VARCHAR(50),
                       status VARCHAR(20) DEFAULT '活跃',
                       created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                       CONSTRAINT fk_users_role FOREIGN KEY (role_id) REFERENCES roles(role_id),
                       CONSTRAINT fk_users_department FOREIGN KEY (department_id) REFERENCES departments(department_id)
);

-- 在 users 表创建后添加此约束
ALTER TABLE departments ADD CONSTRAINT IF NOT EXISTS fk_departments_parent FOREIGN KEY (parent_department_id) REFERENCES departments(department_id);

CREATE TABLE IF NOT EXISTS tasks (
                       task_id INT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) PRIMARY KEY,
                       task_name VARCHAR(255) NOT NULL,
                       description TEXT,
                       creator_id VARCHAR(255),
                       responsible_person_id VARCHAR(255),
                       task_type VARCHAR(50),
                       priority VARCHAR(50),
                       status VARCHAR(50),
                       start_date DATE,
                       end_date DATE,
                       created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                       task_attachments_json TEXT,
    -- 移除 H2 不支持的 ON UPDATE CURRENT_TIMESTAMP，这个逻辑应由 Java Service 实现
                       updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                       CONSTRAINT fk_tasks_creator FOREIGN KEY (creator_id) REFERENCES users(user_id),
                       CONSTRAINT fk_tasks_responsible FOREIGN KEY (responsible_person_id) REFERENCES users(user_id)
);

CREATE TABLE IF NOT EXISTS sub_tasks (
                           sub_task_id INT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) PRIMARY KEY,
                           parent_task_id INT,
                           parent_sub_task_id INT,
                           creator_id VARCHAR(255),
                           sub_task_name VARCHAR(255) NOT NULL,
                           status VARCHAR(50),
                           assigned_to_id VARCHAR(255),
                           start_time TIMESTAMP,
                           end_time TIMESTAMP,
                           deliverable_content TEXT,
                           approval_comment TEXT,
                           created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                           completed_at TIMESTAMP,
    -- 移除 H2 不支持的 ON UPDATE CURRENT_TIMESTAMP
                           updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                           CONSTRAINT fk_subtasks_creator FOREIGN KEY (creator_id) REFERENCES users(user_id),
                           CONSTRAINT fk_subtasks_parent_task FOREIGN KEY (parent_task_id) REFERENCES tasks(task_id),
                           CONSTRAINT fk_subtasks_parent_subtask FOREIGN KEY (parent_sub_task_id) REFERENCES sub_tasks(sub_task_id),
                           CONSTRAINT fk_subtasks_assignee FOREIGN KEY (assigned_to_id) REFERENCES users(user_id)
);

CREATE TABLE IF NOT EXISTS task_members (
                              task_id INT,
                              user_id VARCHAR(255),
                              assigned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                              PRIMARY KEY (task_id, user_id),
                              CONSTRAINT fk_taskmembers_task FOREIGN KEY (task_id) REFERENCES tasks(task_id),
                              CONSTRAINT fk_taskmembers_user FOREIGN KEY (user_id) REFERENCES users(user_id)
);

CREATE TABLE IF NOT EXISTS logs (
                      log_id INT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) PRIMARY KEY,
                      user_id VARCHAR(255),
                      related_task_id INT,
                      related_sub_task_id INT,
                      activity_type VARCHAR(255),
                      description TEXT,
                      location VARCHAR(255),
                      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                      CONSTRAINT fk_logs_user FOREIGN KEY (user_id) REFERENCES users(user_id),
                      CONSTRAINT fk_logs_task FOREIGN KEY (related_task_id) REFERENCES tasks(task_id),
                      CONSTRAINT fk_logs_subtask FOREIGN KEY (related_sub_task_id) REFERENCES sub_tasks(sub_task_id)
);

CREATE TABLE IF NOT EXISTS company_matters (
                                 matter_id INT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) PRIMARY KEY,
                                 title VARCHAR(255) NOT NULL,
                                 content TEXT,
                                 creator_id VARCHAR(255),
                                 importance_level INT,
                                 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                                 CONSTRAINT fk_companymatters_creator FOREIGN KEY (creator_id) REFERENCES users(user_id)
);

CREATE TABLE IF NOT EXISTS deliverables (
                              deliverable_id INT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) PRIMARY KEY,
                              sub_task_id INT,
                              uploader_user_id VARCHAR(255),
                              file_name VARCHAR(255),
                              file_url VARCHAR(255),
                              file_type VARCHAR(100),
                              file_size BIGINT,
                              uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                              CONSTRAINT fk_deliverables_subtask FOREIGN KEY (sub_task_id) REFERENCES sub_tasks(sub_task_id),
                              CONSTRAINT fk_deliverables_uploader FOREIGN KEY (uploader_user_id) REFERENCES users(user_id)
);

-- 种子数据标记表：data.sql 只在这张表为空（即第一次初始化）时插入种子数据，插完写入一行标记。
-- 这样重启不会重复插入，也不会把用户删掉的种子数据重新加回来。
CREATE TABLE IF NOT EXISTS seed_marker (
                             marker_id INT PRIMARY KEY,
                             seeded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
